// Parses the policy library (data/policies/*.md) into section-level chunks with
// metadata, and writes lib/generated/corpus.js so the serverless bundle needs no fs reads.
const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const POLICY_DIR = path.join(ROOT, "data", "policies");
const OUT_DIR = path.join(ROOT, "lib", "generated");

function parseFrontMatter(raw) {
  const m = raw.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  if (!m) throw new Error("Missing front matter");
  const meta = {};
  for (const line of m[1].split("\n")) {
    const i = line.indexOf(":");
    if (i < 0) continue;
    const key = line.slice(0, i).trim();
    let val = line.slice(i + 1).trim().replace(/^"(.*)"$/, "$1");
    meta[key] = val === "" ? null : val;
  }
  return { meta, body: m[2] };
}

function parseTable(lines) {
  const rows = lines
    .filter((l) => l.trim().startsWith("|") && !/^\|\s*-/.test(l.trim()))
    .map((l) => l.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim()));
  if (rows.length < 2) return null;
  return { header: rows[0], rows: rows.slice(1) };
}

function chunkDoc(meta, body) {
  const chunks = [];
  const parts = body.split(/\n(?=## )/);
  for (const part of parts) {
    const h = part.match(/^## (\d+)\.\s+(.+)\n([\s\S]*)$/);
    if (!h) continue;
    const [, num, title, content] = h;
    const lines = content.trim().split("\n");
    const table = parseTable(lines);
    const prose = lines.filter((l) => !l.trim().startsWith("|")).join(" ").replace(/\s+/g, " ").trim();
    const tableText = table ? table.rows.map((r) => table.header.map((hd, i) => `${hd}: ${r[i]}`).join("; ")).join(". ") : "";
    chunks.push({
      id: `${meta.doc_id}-v${meta.version}-s${num}`,
      doc_id: meta.doc_id,
      title: meta.title,
      version: meta.version,
      section: num,
      section_title: title.trim(),
      text: [prose, tableText].filter(Boolean).join(" "),
      prose,
      table,
      country: meta.country,
      audience: meta.audience,
      status: meta.status,
      effective_from: meta.effective_from,
      effective_to: meta.effective_to,
      applies_when: meta.applies_when || null,
      owner: meta.owner,
      source_format: meta.source_format,
      url: `${meta.url}#section-${num}`,
    });
  }
  return chunks;
}

function build() {
  const files = fs.readdirSync(POLICY_DIR).filter((f) => f.endsWith(".md")).sort();
  const docs = [];
  const chunks = [];
  for (const f of files) {
    const { meta, body } = parseFrontMatter(fs.readFileSync(path.join(POLICY_DIR, f), "utf8"));
    const c = chunkDoc(meta, body);
    docs.push({ ...meta, file: f, sections: c.length, words: body.split(/\s+/).length });
    chunks.push(...c);
  }
  const employees = JSON.parse(fs.readFileSync(path.join(ROOT, "data", "meta", "employees.json"), "utf8"));
  const routing = JSON.parse(fs.readFileSync(path.join(ROOT, "data", "meta", "routing.json"), "utf8"));
  fs.mkdirSync(OUT_DIR, { recursive: true });
  const out = `// GENERATED by scripts/build-corpus.js - do not edit by hand.\nmodule.exports = ${JSON.stringify({ docs, chunks, employees, routing }, null, 1)};\n`;
  fs.writeFileSync(path.join(OUT_DIR, "corpus.js"), out);
  console.log(`Corpus: ${docs.length} documents, ${chunks.length} sections, ${employees.length} employee profiles`);
}

build();
